#!/usr/bin/env bash
set -e

echo "=============================================="
echo "  Persian Clock & Calendar - Linux Installer  "
echo "=============================================="

if ! command -v python3 >/dev/null 2>&1; then
    echo "Error: python3 is not installed."
    exit 1
fi

if ! python3 -c "import tkinter" 2>/dev/null; then
    echo "python3-tk is not installed."
    echo "Install it with:"
    echo "  Ubuntu/Debian: sudo apt update && sudo apt install -y python3-tk"
    echo "  Fedora:        sudo dnf install -y python3-tkinter"
    echo "  Arch:          sudo pacman -S tk"
    exit 1
fi

APP_DIR="$HOME/.local/share/persian-clock-widget"
BIN_DIR="$HOME/.local/bin"
APPS_DIR="$HOME/.local/share/applications"
FONTS_DIR="$HOME/.local/share/fonts/PersianClockWidget"
AUTOSTART_DIR="$HOME/.config/autostart"

mkdir -p "$APP_DIR" "$BIN_DIR" "$APPS_DIR" "$FONTS_DIR" "$AUTOSTART_DIR"

echo "[1/4] Extracting application files to $APP_DIR ..."
ARCHIVE_LINE=$(awk '/^__ARCHIVE_BELOW__$/ {print NR + 1; exit 0;}' "$0")
tail -n+"$ARCHIVE_LINE" "$0" | base64 -d | tar -xz -C "$APP_DIR"

echo "[2/4] Installing Persian fonts (Vazir, B Yekan+, Iranian Sans)..."
cp -f "$APP_DIR/assets/fonts/"*.ttf "$FONTS_DIR/" 2>/dev/null || true
command -v fc-cache >/dev/null 2>&1 && fc-cache -f "$FONTS_DIR" >/dev/null 2>&1 || true

echo "[3/4] Creating launcher & desktop menu shortcut..."
cat > "$BIN_DIR/persian-clock-widget" << 'EOF'
#!/usr/bin/env bash
exec python3 "$HOME/.local/share/persian-clock-widget/main.py" "$@"
EOF
chmod +x "$BIN_DIR/persian-clock-widget"

cat > "$APPS_DIR/persian-clock-widget.desktop" << EOF
[Desktop Entry]
Type=Application
Name=Persian Clock & Calendar
Comment=Tehran Clock, Jalali Calendar & Alarms
Exec=$BIN_DIR/persian-clock-widget
Icon=$APP_DIR/assets/icons/app_icon.png
Terminal=false
Categories=Utility;Clock;
EOF

cp -f "$APPS_DIR/persian-clock-widget.desktop" "$AUTOSTART_DIR/persian-clock-widget.desktop"
command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database "$APPS_DIR" >/dev/null 2>&1 || true

echo "[4/4] Installation complete! Launching Persian Clock & Calendar..."
nohup "$BIN_DIR/persian-clock-widget" >/dev/null 2>&1 &
echo "Installed! You can launch it from your Applications Menu or run: persian-clock-widget"
exit 0
